-- Rifts World Book 32: Lemuria - 74 gear rows: Bio-Armor, Bio-Weapons, ranged weapons, symbiotes and transportation
-- 74 gear rows.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~174-lemuria-gear.sql
--
-- Written by scripts/rows-sql.mjs from 3 worker file(s). Every value is
-- printable ASCII and every row cites its book. Rows are keyed on their
-- portable identity, never an id; a row already held is left as it is.

INSERT OR IGNORE INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, mdc, description, source_book, vehicle_slug) VALUES
  ('lemurian-avian-bio-armor', 'Lemurian Avian Bio-Armor', 'rifts', 'armor', 200, NULL, 'Easily worth 6-10 million credits; exclusive to Lemurians and never sold on the open market', 'Clawed gauntlets 2D6 M.D. (Power Strike double, two attacks); clawed feet 3D6 M.D. kick, 4D6 M.D. flying rake or flying kick', 1, 'Hand to hand', NULL, NULL, NULL, NULL, 257, 'Light aerial combat armor (medium power armor equivalent), exclusive to Birdmen Warriors of the Tangata Manu clan and select heroes. M.D.C.: head 110, arms 67 each, clawed hands 37 each, legs 122 each, clawed feet 70 each, wings 117 each, main body 257 (head, hands, feet and wings need a Called Shot at -4). Supernatural P.S. 20. Runs 35 mph at half fatigue; leaps 10 ft, or 30 ft with a run; hovers and flies up to 100 mph (cruise 50, x3 on a ley line or in a ley line triangle, power dive doubles current speed), ceiling 20,000 ft, half speed through forest, silent, for two hours per P.E. point; swims 30 mph (x3 on a ley line), walks the sea floor at half running speed, can dive 300 ft from the air, depth limit 2 miles. -5% to Prowl and Physical skills. Weapons: the clawed gauntlets and feet, two optional side arms and a rifle or long-range power rod. Bonuses: +1 attack at levels 2, 5, 10 and 15; Perception +2 from the air only; strike +2, parry +2, automatic dodge +3, disarm +2, pull punch +1, roll with impact +2; saves against toxic gas, airborne poison and disease +2; Climbing, Land Navigation and Prowl +10%. Optics: telescopic 5,000 ft, nightvision 2,000 ft, see the invisible 300 ft, glare filters. Cold does one-third damage. Senses altitude, depth, wind and currents. Heals its wearer 1 Hit Point or S.D.C. an hour (x2 at a Stone Pyramid, ley line or nexus). Regenerates 2D6 M.D.C. an hour, x2 on ley lines, x3 at a nexus or Stone Pyramid. Needs 15 P.P.E. a day; 570 P.P.E. to create. As with all Bio-Armor (printed 110-111): a living symbiote grown for one owner and useless to anyone else; it needs 1D6+6 hours of wear a week or the bond breaks and it dies 1D6 hours later, as it does after its owner''s death. Goes on in about 15 seconds, can retract but must keep at least 25% of the body covered and reseals in one action; breathes for the wearer in air or water (most suits also hold an hour of emergency air); utility clasps hold gear. Main body at 0 leaves it dormant (wearer -1 attack, -1 on combat bonuses, speed -20%) until it regains 10 M.D.C.; more than 100 below zero kills it.', 'Rifts World Book 32: Lemuria p.111-113', NULL),
  ('lemurian-barnacle-bio-armor', 'Lemurian Barnacle Bio-Armor', 'rifts', 'armor', 130, NULL, 'Easily worth 3-4 million credits; exclusive to Lemurians and never sold on the open market', 'Barnacle Grenade 4D6 M.D. to a 4 foot (1.2 m) blast radius; Barnacle Fists 2D6 M.D. (Power Strike double, two attacks)', 1, 'Barnacle Grenade 350 feet (106.7 m)', '6 barnacle grenades; one regrows per hour', 'Each grenade is one melee attack', NULL, NULL, 147, 'Amphibious combat armor (light power armor equivalent), a mesh studded with barnacles and favoured by spell casters. M.D.C.: head 90 (Called Shot at -4), arms 50 each, legs 85 each, main body 147. Supernatural P.S. 20. Runs 35 mph at half fatigue; leaps 10 ft, or 16 ft with a run; no flight; swims 30 mph (x3 on a ley line), walks the sea floor at half running speed, depth limit 3 miles. No movement penalties. Weapons: launched explosive barnacles, barnacle-edged fists and two optional side arms. Bonuses: +1 attack at levels 3, 7 and 11; Perception +2 underwater only; strike +1, parry +1, disarm +1, pull punch +1, roll with impact +2; saves against toxic gas, poison and disease +6; Climbing, Underwater Navigation and Undersea Salvage +10%. P.P.E. reservoir: the barnacles hold 1D4x10+50 P.P.E. at full, which the wearer may spend on spells, and regain 5D6 an hour. Regenerates 3D6 M.D.C. an hour. Needs 20 P.P.E. a day; 750 P.P.E. to create. Barnacles outlive the suit. As with all Bio-Armor (printed 110-111): a living symbiote grown for one owner and useless to anyone else; it needs 1D6+6 hours of wear a week or the bond breaks and it dies 1D6 hours later, as it does after its owner''s death. Goes on in about 15 seconds, can retract but must keep at least 25% of the body covered and reseals in one action; breathes for the wearer in air or water (most suits also hold an hour of emergency air); utility clasps hold gear. Main body at 0 leaves it dormant (wearer -1 attack, -1 on combat bonuses, speed -20%) until it regains 10 M.D.C.; more than 100 below zero kills it.', 'Rifts World Book 32: Lemuria p.113-114', NULL),
  ('lemurian-chitin-bio-armor', 'Lemurian Chitin Bio-Armor', 'rifts', 'armor', 180, NULL, 'Easily worth 5-8 million credits; exclusive to Lemurians and never sold on the open market', 'Shoulder Beams 2D6 M.D. single, 4D6 M.D. dual blast; Serrated Forearm Blades 4D6 M.D. (Power Strike double, two attacks); Insect Mandibles 2D4 M.D.', 1, 'Shoulder Beams 1,600 feet (488 m)', 'Effectively unlimited while the suit is charged with P.P.E.', 'Each single or dual blast is one melee action', NULL, NULL, 268, 'Amphibious combat armor (medium power armor equivalent) of insect plate with four wings. M.D.C.: antennae 10 each, head 100, hands 57 each, arms 95 each, legs 157 each, four insect wings at 35 apiece, main body 268 (antennae, head, hands and wings need a Called Shot at -4; losing one pair of wings ends flight). Supernatural P.S. 25. Runs 35 mph at a quarter fatigue; leaps 20 ft up or 40 ft along from standing, double with a run; hovers and flies 50 mph (x3 on a ley line or in a ley line triangle, power dive doubles speed), ceiling 10,000 ft, buzz heard within 500 ft, for two hours per P.E. point (half that underwater); swims 30 mph (x3 on a ley line), sea floor at half running speed, depth limit 3 miles. No movement penalties. Hand to hand: 4D6 S.D.C. restrained punch, 2D6 M.D. punch/head butt, 4D6 M.D. power punch, 3D6 M.D. kick, 5D6 M.D. leap or power kick, 1D6 M.D. stomp, 2D6 M.D. body block with 01-50% knockdown of foes up to 14 ft tall (lose initiative and one attack). Bonuses: +1 attack at levels 2, 5, 10 and 15; Perception +2 on land only; strike +2, parry +2, automatic dodge +1 at levels 1, 3, 5, 7, 9 and 11, disarm +2, pull punch +3, roll with impact +2; saves against toxic gas, airborne poison and disease +2; Climbing and Rappelling +15%, Land Navigation and Tailing +10%, Prowl +5%. Has the Avian suit''s optics, cold resistance, wearer healing and altitude/depth sense; antennae detect radar within 10 miles and sonar within 20, giving direction, distance and whether a sonar pulse is living or mechanical. Regenerates 2D6 M.D.C. an hour, x2 on ley lines, x3 at a nexus or Stone Pyramid. Needs 20 P.P.E. a day; 900 P.P.E. to create. As with all Bio-Armor (printed 110-111): a living symbiote grown for one owner and useless to anyone else; it needs 1D6+6 hours of wear a week or the bond breaks and it dies 1D6 hours later, as it does after its owner''s death. Goes on in about 15 seconds, can retract but must keep at least 25% of the body covered and reseals in one action; breathes for the wearer in air or water (most suits also hold an hour of emergency air); utility clasps hold gear. Main body at 0 leaves it dormant (wearer -1 attack, -1 on combat bonuses, speed -20%) until it regains 10 M.D.C.; more than 100 below zero kills it.', 'Rifts World Book 32: Lemuria p.114-115', NULL),
  ('lemurian-coral-bio-armor', 'Lemurian Coral Bio-Armor', 'rifts', 'armor', 600, NULL, 'Easily worth 12-15 million credits; exclusive to Lemurians and never sold on the open market', 'Coral Burst 6D6 M.D. from one arm, 1D6x10+6 M.D. dual blast; Retractable Arm Blades 5D6 M.D. (Power Strike double, two attacks)', 1, 'Coral Burst 1,000 feet (305 m) underwater, double in an atmosphere', '60 blasts per arm, per hour', 'Each single or dual blast is one melee attack', NULL, NULL, 357, 'Amphibious combat armor (heavy power armor equivalent) grown from reef polyps. M.D.C.: head 120, hands 90 each, arms 180 each, arm sword blades 60 each, legs 220 each, main body 357 (head, hands and blades need a Called Shot at -4). Supernatural P.S. 30. Runs 30 mph at one-third fatigue; leaps 5 ft, or 10 ft with a run; no flight; swims 30 mph (x3 on a ley line), sea floor at half running speed, depth limit 4 miles. -10% to Prowl and Physical skills. Hand to hand: 5D6 S.D.C. restrained punch, 3D6 M.D. punch/head butt, 6D6 M.D. power punch, 3D6+2 M.D. kick, 1D6 M.D. stomp, 3D6+2 M.D. body block with 01-60% knockdown of foes up to 15 ft tall (lose initiative and one attack). Bonuses: +1 attack at levels 2, 5, 10 and 15; Perception +2 underwater only; Coral Burst strike +1 at each of levels 2, 4, 6, 8, 10 and 12; strike +1, parry +2, disarm +2, pull punch +3, roll with impact +2; saves against toxic gas, airborne poison and disease +2; Prowl and Camouflage +10% in coral reefs only. Razor Coral: twice an hour, for one minute, unarmed attackers suffer half the damage they deal and melee weapons deal 20% less. Regenerates 3D6 M.D.C. an hour, double at a reef. Needs 25 P.P.E. a day; 700 P.P.E. to create. As with all Bio-Armor (printed 110-111): a living symbiote grown for one owner and useless to anyone else; it needs 1D6+6 hours of wear a week or the bond breaks and it dies 1D6 hours later, as it does after its owner''s death. Goes on in about 15 seconds, can retract but must keep at least 25% of the body covered and reseals in one action; breathes for the wearer in air or water (most suits also hold an hour of emergency air); utility clasps hold gear. Main body at 0 leaves it dormant (wearer -1 attack, -1 on combat bonuses, speed -20%) until it regains 10 M.D.C.; more than 100 below zero kills it.', 'Rifts World Book 32: Lemuria p.115-117', NULL),
  ('lemurian-crustacean-bio-armor', 'Lemurian Crustacean Bio-Armor', 'rifts', 'armor', 1400, NULL, 'Easily worth 18-25 million credits; exclusive to Lemurians and never sold on the open market', 'Sonic Wave 1D6x10 M.D. to targets 12 feet (3.6 m) or larger, or 3D6 M.D. to everything within 15 feet (4.6 m) of impact; Chest Beam 2D6 M.D.; Giant Crab Claw 6D6+10 M.D., 1D6x10 M.D. Power Strike (two attacks)', 1, 'Sonic Wave 600 feet (183 m) on the surface, 1,200 feet (366 m) underwater; Chest Beam 1,600 feet (488 m), half underwater', 'Effectively unlimited while the suit is charged with P.P.E.', 'Each wave or blast is one melee attack', NULL, NULL, 457, 'Heavy amphibious combat armor (heavy power armor equivalent), 9-12 ft tall and 1,400-2,000 lbs. M.D.C.: head 150, hand (one, usually right) 130, pincer claw (one, usually left) 350, arms 220 each, legs 310 each, main body 457 (head and hand need a Called Shot at -4). Supernatural P.S. 40. Runs 30 mph at a quarter fatigue; no standing jump, 8 ft with a run; no flight; swims 35 mph (x3 on a ley line), sea floor at half running speed, depth limit 7 miles. -15% to Acrobatics, Gymnastics, Prowl and similar agility skills, but not Climbing or Swimming. Hand to hand: 6D6 S.D.C. restrained punch, 5D6 M.D. punch/head butt, 1D6x10 M.D. power punch, 1D4x10+10 M.D. crab claw, 3D6 M.D. stomp, 6D6 M.D. body block with 01-78% knockdown of foes up to 20 ft tall (lose initiative and one attack). Bonuses: +1 attack at levels 2, 4, 8, 12 and 15; Perception +3 underwater, +2 on land; strike +2, parry +3, dodge +1 underwater only, disarm +2, pull punch +2, roll with impact +3; saves against toxic gas, airborne poison and disease +6; Underwater and Land Navigation +10%. Emergency flotation shoots the suit straight to the surface unharmed; anything it is grappling may suffer the bends. Hammerhead eyes see a near 300 degree arc, leaving only a small blind spot behind. Regenerates 1D6x10 M.D.C. an hour. Needs 30 P.P.E. a day; 1,000 P.P.E. to create. As with all Bio-Armor (printed 110-111): a living symbiote grown for one owner and useless to anyone else; it needs 1D6+6 hours of wear a week or the bond breaks and it dies 1D6 hours later, as it does after its owner''s death. Goes on in about 15 seconds, can retract but must keep at least 25% of the body covered and reseals in one action; breathes for the wearer in air or water (most suits also hold an hour of emergency air); utility clasps hold gear. Main body at 0 leaves it dormant (wearer -1 attack, -1 on combat bonuses, speed -20%) until it regains 10 M.D.C.; more than 100 below zero kills it.', 'Rifts World Book 32: Lemuria p.119-120', NULL),
  ('lemurian-dolphin-bio-armor', 'Lemurian Dolphin Bio-Armor', 'rifts', 'armor', 100, NULL, 'Easily worth 6-10 million credits; exclusive to Lemurians and never sold on the open market', 'Energy Bolt 2D6 M.D. (single shots only); Tail Slap 3D6 M.D. (counts as two melee attacks)', 1, 'Energy Bolt 1,600 feet (488 m), half underwater; Tail Slap about 12 feet (3.6 m)', 'Effectively unlimited while the suit is charged with P.P.E.', 'Each blast is one melee attack', NULL, NULL, 195, 'Undersea combat armor (light power armor equivalent) with a detachable dolphin tail, worn almost only by Scouts and Sea Sentinels. M.D.C.: head 90 (Called Shot at -4), arms 90 each, legs 120 each, the tail section 221, main body 195. Supernatural P.S. 20. Weighs 100 lbs, plus 250 for the tail. Runs 40 mph at half fatigue; leaps 10 ft, or 20 ft with a run; no flight; swims 50 mph (x3 on a ley line, halved without the tail), leaps 20 ft out of the water, moves over the sea floor at full running speed, depth limit 4 miles. No movement penalties, but the suit cannot be used on land with the tail on. Hand to hand as printed: 1D6 M.D. restrained punch, 2D6 M.D. power punch (two attacks), 3D6 M.D. tail slap. Bonuses: +1 attack at levels 2, 6, 10 and 15; Perception +2 underwater only; strike +1, parry +2, automatic dodge +1 at levels 1, 3, 5, 7, 10 and 13, disarm +1, pull punch +2, roll with impact +1; saves against toxic gas, airborne poison and disease +2; Underwater Navigation, Track and Hunt Sea Animals and Prowl +15% (none of these apply on land). The removed tail acts as an independent creature that obeys commands, waits indefinitely and answers a telepathic call from up to 3,000 miles. Regenerates 2D6+2 M.D.C. an hour. Needs 15 P.P.E. a day; 800 P.P.E. to create. As with all Bio-Armor (printed 110-111): a living symbiote grown for one owner and useless to anyone else; it needs 1D6+6 hours of wear a week or the bond breaks and it dies 1D6 hours later, as it does after its owner''s death. Goes on in about 15 seconds, can retract but must keep at least 25% of the body covered and reseals in one action; breathes for the wearer in air or water (most suits also hold an hour of emergency air); utility clasps hold gear. Main body at 0 leaves it dormant (wearer -1 attack, -1 on combat bonuses, speed -20%) until it regains 10 M.D.C.; more than 100 below zero kills it.', 'Rifts World Book 32: Lemuria p.120-121', NULL),
  ('lemurian-kelp-bio-armor', 'Lemurian Kelp Bio-Armor', 'rifts', 'armor', 150, NULL, 'Easily worth 6-10 million credits; exclusive to Lemurians and never sold on the open market', 'Kelp Whip 3D6 S.D.C., or 2D6 M.D. when charged with Bio-Energy (double to undead); Kelp Blades 1D4 M.D., 4D4 M.D. to undead', 1, 'Kelp Whip 15 feet (4.6 m) as a whip, 50 feet (15 m) as a rope, lasso or towline; Kelp Blades 80 feet (24.4 m) thrown', '8 kelp blades; one regrows per hour', 'Each thrown blade is one melee attack', NULL, NULL, 247, 'Undersea combat and reconnaissance armor (medium power armor equivalent) worn by Serpent Hunters, Scouts and ambush teams. M.D.C.: head 100 (Called Shot at -4), arms 97 each, legs 130 each, main body 247. Supernatural P.S. 22. Runs 40 mph at one-third fatigue; leaps 10 ft, or 20 ft with a run; no flight; swims 40 mph (x3 on a ley line), sea floor at half running speed, depth limit 3 miles. No movement penalties. The prehensile whip grips, disarms, trips, binds and hauls its wearer up a climb; it cannot be detached, takes 30 M.D. to cut and regrows one foot an hour. Hand to hand: 3D6 S.D.C. restrained punch, 1D6 M.D. punch/head butt, 2D6 M.D. power punch (two attacks), 2D4 M.D. kick. Bonuses: +1 attack at levels 2, 5, 10 and 15; Perception +1 underwater only; strike +1, parry +2, disarm +3, entangle +3, pull punch +1, roll with impact +1; saves against toxic gas, airborne poison and disease +2; Climbing and Rappelling +15%; Land Navigation, Underwater Navigation and Prowl +10%. Sonar masking: -15% to Sensory Equipment rolls to find the suit by sonar. Camouflage as the skill at 45% in the open, 65% in seaweed beds, 85% in kelp forests. Regenerates 2D6 M.D.C. an hour, double inside a kelp patch or coral reef. Needs 20 P.P.E. a day; 650 P.P.E. to create. As with all Bio-Armor (printed 110-111): a living symbiote grown for one owner and useless to anyone else; it needs 1D6+6 hours of wear a week or the bond breaks and it dies 1D6 hours later, as it does after its owner''s death. Goes on in about 15 seconds, can retract but must keep at least 25% of the body covered and reseals in one action; breathes for the wearer in air or water (most suits also hold an hour of emergency air); utility clasps hold gear. Main body at 0 leaves it dormant (wearer -1 attack, -1 on combat bonuses, speed -20%) until it regains 10 M.D.C.; more than 100 below zero kills it.', 'Rifts World Book 32: Lemuria p.121-123', NULL),
  ('lemurian-leviathan-bio-armor', 'Lemurian Leviathan Bio-Armor', 'rifts', 'armor', 700, NULL, 'Easily worth 10-14 million credits; exclusive to Lemurians and never sold on the open market', 'Light Stonecaster Cannon: Sedimentary Rock 3D6 M.D. to a 15 foot (4.6 m) area, Igneous Molten Rock 4D6 M.D. plus 2D6 M.D. for each of the next two melee rounds, Metamorphic Stone (armor piercing) 6D6 M.D.; Shoulder Laser 3D6 M.D.; Clawed Gauntlets 4D6+4 M.D. (Power Strike double, two attacks)', 1, 'Stonecaster Cannon 4,000 feet (1,219 m), half underwater; Shoulder Searchlight and Laser 1,200 feet (366 m)', 'Cannon 60 blasts of any type; regains one a minute on a ley line, nexus or stone pyramid, all 60 for 60 P.P.E. from a mage, otherwise one per hour. Laser effectively unlimited', 'Each shot is one melee attack', NULL, NULL, 327, 'Amphibious heavy combat armor (heavy power armor equivalent), also called Serpent Bio-Armor, exclusive to Serpent Hunters and made from their Thrall Sea Serpent. M.D.C.: head 140, hands/gauntlets 95 each, arms 170 each, shoulder light/laser 35, shoulder cannon 140, legs 230 each, main body 327 (head, hands and light/laser need a Called Shot at -4). Supernatural P.S. 30. Runs 30 mph at one-tenth fatigue; leaps 8 ft, or 16 ft with a run; no flight; swims 30 mph (x3 on a ley line), sea floor at half running speed, depth limit 6 miles. -10% to Acrobatics, Climbing, Prowl and similar agility skills. Hand to hand: 5D6 S.D.C. restrained punch, 3D6 M.D. punch/head butt, 6D6 M.D. power punch, 3D6+2 M.D. kick, 1D6 M.D. stomp, 3D6+2 M.D. body block with 01-60% knockdown of foes up to 15 ft tall. Bonuses: +1 attack at levels 2, 5, 7, 9, 11 and 15; Perception +2 underwater only; initiative +2, strike +3, parry +3, dodge +1, disarm +2, pull punch +4, roll with impact +3; saves against toxic gas, airborne poison and disease +3; Land and Underwater Navigation +10%. Immune to dragon fire; other dragon breath does half. Magic resistance: magic and psionic energy attacks do half damage, +5 to save against illusions, +3 against possession and mind control; physical, kinetic and cold attacks do full. Spell nullification: cancels up to three incoming spells or psionic attacks per 24 hours, +1 per further level, when switched on; one use returns every three hours, faster on a ley line or in a stone pyramid. Has the Avian suit''s optics, cold resistance, wearer healing and depth sense. Regenerates 4D6 M.D.C. an hour, triple at ley lines, nexus points and stone pyramids. Needs 25 P.P.E. a day; 2,000 P.P.E. to create. As with all Bio-Armor (printed 110-111): a living symbiote grown for one owner and useless to anyone else; it needs 1D6+6 hours of wear a week or the bond breaks and it dies 1D6 hours later, as it does after its owner''s death. Goes on in about 15 seconds, can retract but must keep at least 25% of the body covered and reseals in one action; breathes for the wearer in air or water (most suits also hold an hour of emergency air); utility clasps hold gear. Main body at 0 leaves it dormant (wearer -1 attack, -1 on combat bonuses, speed -20%) until it regains 10 M.D.C.; more than 100 below zero kills it.', 'Rifts World Book 32: Lemuria p.123-126', NULL),
  ('lemurian-shark-bio-armor', 'Lemurian Shark Bio-Armor', 'rifts', 'armor', 220, NULL, 'Easily worth 7-11 million credits; exclusive to Lemurians and never sold on the open market', 'Electric Arc 3D6+3 M.D.; Shark Bite 3D6+2 M.D.; Shark Tooth Blades/Spikes 3D6 M.D.', 1, 'Electric Arc 1,500 feet (457 m) in air, 500 feet (152 m) underwater', 'Effectively unlimited while the suit is charged with P.P.E.', 'Each blast or bite is one melee attack', NULL, NULL, 255, 'Blood-red undersea combat armor (medium power armor equivalent), exclusive to elite Oceanic Guardsmen. M.D.C.: head 135, hands 55 each, arms 120 each, legs 160 each, main body 255 (head and hands need a Called Shot at -4). Supernatural P.S. 25. Runs 50 mph at one-third fatigue; leaps 10 ft, or 20 ft with a run; no flight; swims 45 mph (x3 on a ley line), sea floor at half running speed, depth limit 5 miles. -5% to Prowl and Physical skills. Hand to hand: 4D6 S.D.C. restrained punch, 2D6 M.D. punch/head butt, 4D6 M.D. power punch, 3D6 M.D. kick, 4D6 M.D. leap or power kick (two attacks), 1D4 M.D. stomp. Bonuses: +1 attack at levels 2, 5, 9, 12 and 15; Perception +2 underwater only; initiative +1, strike +2, parry +1, automatic dodge +3, disarm +1 at levels 2, 5, 8, 11 and 15, pull punch +2, roll with impact +2; saves against toxic gas, airborne poison and disease +2; +1 to save against Horror Factor at levels 1, 3, 5, 6, 8, 10, 12 and 14; Underwater Navigation and Prowl +10%. Combat frenzy when outnumbered over 3 to 1, facing impossible odds or when he or an ally is about to die: +1D6x10 M.D.C., +1 attack, +2 initiative, +2 strike, +3 M.D. damage, critical on 17+, double damage from behind, triple on a natural 20, +10% against coma/death; but -9 Perception, no bonus to dodge, disarm, pull punch or roll, -20% on skills, and only 01-60% to recognise friends (rolled again before a killing blow). Afterwards he must rest 15 minutes or be at -2 attacks, half Spd, -3 Perception, -2 on initiative, strike, parry, dodge, disarm and entangle, -10% on skills. Smells blood 10 miles off in water, 1 mile on land (tracks it at 50% +2% per level). Optional hammerhead helmet: 300 degree sight, +1 Perception, parry and dodge, +20 helmet M.D.C. Regenerates 2D6 M.D.C. an hour. Needs 20 P.P.E. a day; 1,200 P.P.E. to create. As with all Bio-Armor (printed 110-111): a living symbiote grown for one owner and useless to anyone else; it needs 1D6+6 hours of wear a week or the bond breaks and it dies 1D6 hours later, as it does after its owner''s death. Goes on in about 15 seconds, can retract but must keep at least 25% of the body covered and reseals in one action; breathes for the wearer in air or water (most suits also hold an hour of emergency air); utility clasps hold gear. Main body at 0 leaves it dormant (wearer -1 attack, -1 on combat bonuses, speed -20%) until it regains 10 M.D.C.; more than 100 below zero kills it.', 'Rifts World Book 32: Lemuria p.126-128', NULL),
  ('lemurian-wood-bio-armor', 'Lemurian Wood Bio-Armor', 'rifts', 'armor', 240, NULL, 'Easily worth 5-8 million credits; exclusive to Lemurians and never sold on the open market', 'Razorshell Launcher 2D6 M.D. per single shot; Arm Spines 4D6 M.D. (Power Strike double, two attacks); thorns add 1D6 M.D. to close combat attacks', 1, 'Razorshell Launcher 2,000 feet (609 m), half underwater', '120 shells; fully recharged in one hour on a ley line or at a stone pyramid, otherwise 1D4x10 shells per hour', 'Each shell is one melee attack', NULL, NULL, 277, 'Amphibious combat armor (medium power armor equivalent) that looks carved from driftwood. M.D.C.: head 95, hands 55 each, arms 95 each, legs 145 each, main body 277 (head and hands need a Called Shot at -4). Supernatural P.S. 22. Runs 40 mph at half fatigue; leaps 10 ft, or 20 ft with a run; no flight; swims 30 mph underwater and 45 mph on the surface (x3 on a ley line), sea floor at half running speed, depth limit 4 miles. -5% to Prowl and Physical skills. Hand to hand, all doing double damage to vampires, undead and anything vulnerable to wood: 4D6 S.D.C. restrained punch, 2D6 M.D. punch/head butt, 4D6 M.D. power punch, 3D6 M.D. kick, 4D6 M.D. leap or power kick (two attacks), 1D4 M.D. stomp. Bonuses: +1 attack at levels 2, 5, 10 and 15; Perception +2 on land only; strike +1, parry +3, disarm +2, pull punch +2, roll with impact +3; saves against toxic gas, airborne poison and disease +2; Climbing and Land Navigation +10%; in woods only, Prowl +15% and Camouflage at 85%. Solar boost in open sunlight or water under 100 ft deep: P.S. 25, running 75 mph and 1D6 M.D. regenerated per minute, fading 1D6 minutes after losing the sun. Thorns can be extruded at will from fists, shoulders, elbows, knees and feet. Regenerates 3D6 M.D.C. an hour. Needs 20 P.P.E. a day; 650 P.P.E. to create. As with all Bio-Armor (printed 110-111): a living symbiote grown for one owner and useless to anyone else; it needs 1D6+6 hours of wear a week or the bond breaks and it dies 1D6 hours later, as it does after its owner''s death. Goes on in about 15 seconds, can retract but must keep at least 25% of the body covered and reseals in one action; breathes for the wearer in air or water (most suits also hold an hour of emergency air); utility clasps hold gear. Main body at 0 leaves it dormant (wearer -1 attack, -1 on combat bonuses, speed -20%) until it regains 10 M.D.C.; more than 100 below zero kills it.', 'Rifts World Book 32: Lemuria p.128-129', NULL),
  ('lemurian-wave-strider-body-armor', 'Wave Strider Body Armor', 'rifts', 'armor', 19, 120000, '120,000-185,000 credits on the black market along ocean routes and at Atlantis; rare. Never sold on the open market by Lemurians', NULL, 1, NULL, NULL, NULL, NULL, NULL, 87, 'Light commercial amphibious body armor, the everyday survival suit of Lemurian scouts, explorers, sailors, academics and surface visitors. Grown by Biomancy but not a true symbiotic Bio-Armor: it is not linked to one wearer, so outsiders can get one. M.D.C.: head/helmet 55, hands 18, arms 35 each, legs 45 each, and 87 for the main body (head and hands need a Called Shot at -3). Adds 3 inches of height, 9 with the folding head crest. No movement penalties. Regenerates 2D6 M.D.C. every 24 hours. Lets air-breathers breathe underwater indefinitely; depth tolerance 2.5 miles; helmet depth gauge and compass; +10% to Swimming from webbed fingers and membranes; adjustable buoyancy lets it serve as a life preserver; cold does one-third damage. Wave striding: the boots let the wearer walk or run on the water''s surface; waves over 3 ft cut speed 20%, up to 9 ft by half, 10-20 ft by 75%, and anything bigger allows floating only.', 'Rifts World Book 32: Lemuria p.129-131', NULL),
  ('lemurian-barracuda-bio-blade-dagger-knife', 'Barracuda Bio-Blade: Dagger/Knife', 'rifts', 'weapon', NULL, NULL, 'Never sold by Lemurians; all Bio-Weapons are valued as magic weapons at 50,000-200,000 credits depending on the weapon, its damage and special abilities (general figure, printed 131).', '2D4 M.D.', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Survival knife. A filter duct in the handle strips salt from water to make it drinkable, and the serrated edge works as a saw: +2% to Wilderness Survival and to Undersea and Sea Survival. A silver, serrated, finned blade favoured by Lemurian and Meran Wilderness Sea Scouts; 300-440 P.P.E. to create. Unlike Bone and Shell blades it gets no throwing enhancement. As a Lemurian melee Bio-Weapon it can hurt beings harmed only by special attacks (vampires, werebeasts and the like), has 1D6x10+20 M.D.C. of its own if targeted, regrowing 1D6 M.D.C. per minute, and needs no host.', 'Rifts World Book 32: Lemuria p.131', NULL),
  ('lemurian-barracuda-bio-blade-spear', 'Barracuda Bio-Blade: Spear', 'rifts', 'weapon', NULL, NULL, 'Never sold by Lemurians; all Bio-Weapons are valued as magic weapons at 50,000-200,000 credits depending on the weapon, its damage and special abilities (general figure, printed 131).', '2D6 M.D.', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'A hooked blade with serrated teeth on the other side and a special grip suit it to spearfishing, handling large prey, cutting ropes at a distance and butchering big fish and animals: +2% to the Fishing skill. A silver, serrated, finned blade favoured by Lemurian and Meran Wilderness Sea Scouts; 300-440 P.P.E. to create. Unlike Bone and Shell blades it gets no throwing enhancement. As a Lemurian melee Bio-Weapon it can hurt beings harmed only by special attacks (vampires, werebeasts and the like), has 1D6x10+20 M.D.C. of its own if targeted, regrowing 1D6 M.D.C. per minute, and needs no host. As a long weapon it may be of the collapsible kind, folding to one-third length (about 2 ft/0.6 m) for carrying.', 'Rifts World Book 32: Lemuria p.131', NULL),
  ('lemurian-barracuda-bio-blade-large-sword', 'Barracuda Bio-Blade: Large Sword', 'rifts', 'weapon', NULL, NULL, 'Never sold by Lemurians; all Bio-Weapons are valued as magic weapons at 50,000-200,000 credits depending on the weapon, its damage and special abilities (general figure, printed 131).', '2D6+2 M.D.', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'The large form of the Barracuda Sword. Serrated along the top edge, with a pry bar at the hilt and a pommel shaped as a can opener, for opening sunken ships, locked cabinets, oysters and clams: +2% to Undersea Salvage. A silver, serrated, finned blade favoured by Lemurian and Meran Wilderness Sea Scouts; 300-440 P.P.E. to create. Unlike Bone and Shell blades it gets no throwing enhancement. As a Lemurian melee Bio-Weapon it can hurt beings harmed only by special attacks (vampires, werebeasts and the like), has 1D6x10+20 M.D.C. of its own if targeted, regrowing 1D6 M.D.C. per minute, and needs no host.', 'Rifts World Book 32: Lemuria p.131', NULL),
  ('lemurian-barracuda-bio-blade-short-sword', 'Barracuda Bio-Blade: Short Sword', 'rifts', 'weapon', NULL, NULL, 'Never sold by Lemurians; all Bio-Weapons are valued as magic weapons at 50,000-200,000 credits depending on the weapon, its damage and special abilities (general figure, printed 131).', '2D4 M.D.', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'The short form of the Barracuda Sword. Serrated along the top edge, with a pry bar at the hilt and a pommel shaped as a can opener, for opening sunken ships, locked cabinets, oysters and clams: +2% to Undersea Salvage. A silver, serrated, finned blade favoured by Lemurian and Meran Wilderness Sea Scouts; 300-440 P.P.E. to create. Unlike Bone and Shell blades it gets no throwing enhancement. As a Lemurian melee Bio-Weapon it can hurt beings harmed only by special attacks (vampires, werebeasts and the like), has 1D6x10+20 M.D.C. of its own if targeted, regrowing 1D6 M.D.C. per minute, and needs no host.', 'Rifts World Book 32: Lemuria p.131', NULL),
  ('lemurian-barracuda-bio-blade-trident', 'Barracuda Bio-Blade: Trident', 'rifts', 'weapon', NULL, NULL, 'Never sold by Lemurians; all Bio-Weapons are valued as magic weapons at 50,000-200,000 credits depending on the weapon, its damage and special abilities (general figure, printed 131).', '3D6 M.D.', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Teeth, notches, ridges and holes along the trident turn it into an underwater surveying instrument when stood upright with its butt in the sand: +2% to Ocean Geographic Surveying. A silver, serrated, finned blade favoured by Lemurian and Meran Wilderness Sea Scouts; 300-440 P.P.E. to create. Unlike Bone and Shell blades it gets no throwing enhancement. As a Lemurian melee Bio-Weapon it can hurt beings harmed only by special attacks (vampires, werebeasts and the like), has 1D6x10+20 M.D.C. of its own if targeted, regrowing 1D6 M.D.C. per minute, and needs no host. As a long weapon it may be of the collapsible kind, folding to one-third length (about 2 ft/0.6 m) for carrying.', 'Rifts World Book 32: Lemuria p.131', NULL),
  ('lemurian-bone-shell-bio-weapon-club-war-club', 'Bone & Shell Bio-Weapon: Club/War Club', 'rifts', 'weapon', NULL, NULL, 'Never sold by Lemurians; all Bio-Weapons are valued as magic weapons at 50,000-200,000 credits depending on the weapon, its damage and special abilities (general figure, printed 131).', '2D4 M.D.', 1, '100 feet (30.5 m) thrown', NULL, NULL, NULL, NULL, NULL, 'Bone or shell club/war club that can be thrown 100 feet (30.5 m) and comes back by magic. Grown from a vertebrate or a crustacean, with a jagged edge like a crab claw or clamshell; enchanted to return to the thrower. 500-650 P.P.E. to create. As a Lemurian melee Bio-Weapon it can hurt beings harmed only by special attacks (vampires, werebeasts and the like), has 1D6x10+20 M.D.C. of its own if targeted, regrowing 1D6 M.D.C. per minute, and needs no host.', 'Rifts World Book 32: Lemuria p.131', NULL),
  ('lemurian-bone-shell-bio-weapon-dagger-knife', 'Bone & Shell Bio-Weapon: Dagger/Knife', 'rifts', 'weapon', NULL, NULL, 'Never sold by Lemurians; all Bio-Weapons are valued as magic weapons at 50,000-200,000 credits depending on the weapon, its damage and special abilities (general figure, printed 131).', '1D6 M.D.', 1, '200 feet (6.1 m as printed) thrown', NULL, NULL, NULL, NULL, NULL, 'Bone or shell dagger/knife that can be thrown 200 feet (6.1 m as printed) and comes back by magic. Grown from a vertebrate or a crustacean, with a jagged edge like a crab claw or clamshell; enchanted to return to the thrower. 500-650 P.P.E. to create. As a Lemurian melee Bio-Weapon it can hurt beings harmed only by special attacks (vampires, werebeasts and the like), has 1D6x10+20 M.D.C. of its own if targeted, regrowing 1D6 M.D.C. per minute, and needs no host.', 'Rifts World Book 32: Lemuria p.131-132', NULL),
  ('lemurian-bone-shell-bio-weapon-spear', 'Bone & Shell Bio-Weapon: Spear', 'rifts', 'weapon', NULL, NULL, 'Never sold by Lemurians; all Bio-Weapons are valued as magic weapons at 50,000-200,000 credits depending on the weapon, its damage and special abilities (general figure, printed 131).', '2D6 M.D.', 1, '500 feet (152 m) thrown', NULL, NULL, NULL, NULL, NULL, 'Bone or shell spear that can be thrown 500 feet (152 m) and comes back by magic. As a long weapon it may be of the collapsible kind, folding to one-third length (about 2 ft/0.6 m) for carrying. Grown from a vertebrate or a crustacean, with a jagged edge like a crab claw or clamshell; enchanted to return to the thrower. 500-650 P.P.E. to create. As a Lemurian melee Bio-Weapon it can hurt beings harmed only by special attacks (vampires, werebeasts and the like), has 1D6x10+20 M.D.C. of its own if targeted, regrowing 1D6 M.D.C. per minute, and needs no host.', 'Rifts World Book 32: Lemuria p.131-132', NULL),
  ('lemurian-bone-shell-bio-weapon-large-sword', 'Bone & Shell Bio-Weapon: Large Sword', 'rifts', 'weapon', NULL, NULL, 'Never sold by Lemurians; all Bio-Weapons are valued as magic weapons at 50,000-200,000 credits depending on the weapon, its damage and special abilities (general figure, printed 131).', '2D6+2 M.D.', 1, '150 feet (45 m) thrown', NULL, NULL, NULL, NULL, NULL, 'Bone or shell large sword that can be thrown 150 feet (45 m) and comes back by magic. The large form of the Bone or Shell Sword. Grown from a vertebrate or a crustacean, with a jagged edge like a crab claw or clamshell; enchanted to return to the thrower. 500-650 P.P.E. to create. As a Lemurian melee Bio-Weapon it can hurt beings harmed only by special attacks (vampires, werebeasts and the like), has 1D6x10+20 M.D.C. of its own if targeted, regrowing 1D6 M.D.C. per minute, and needs no host.', 'Rifts World Book 32: Lemuria p.131-132', NULL),
  ('lemurian-bone-shell-bio-weapon-short-sword', 'Bone & Shell Bio-Weapon: Short Sword', 'rifts', 'weapon', NULL, NULL, 'Never sold by Lemurians; all Bio-Weapons are valued as magic weapons at 50,000-200,000 credits depending on the weapon, its damage and special abilities (general figure, printed 131).', '2D4 M.D.', 1, '150 feet (45 m) thrown', NULL, NULL, NULL, NULL, NULL, 'Bone or shell short sword that can be thrown 150 feet (45 m) and comes back by magic. The short form of the Bone or Shell Sword. Grown from a vertebrate or a crustacean, with a jagged edge like a crab claw or clamshell; enchanted to return to the thrower. 500-650 P.P.E. to create. As a Lemurian melee Bio-Weapon it can hurt beings harmed only by special attacks (vampires, werebeasts and the like), has 1D6x10+20 M.D.C. of its own if targeted, regrowing 1D6 M.D.C. per minute, and needs no host.', 'Rifts World Book 32: Lemuria p.131-132', NULL),
  ('lemurian-bone-shell-bio-weapon-trident', 'Bone & Shell Bio-Weapon: Trident', 'rifts', 'weapon', NULL, NULL, 'Never sold by Lemurians; all Bio-Weapons are valued as magic weapons at 50,000-200,000 credits depending on the weapon, its damage and special abilities (general figure, printed 131).', '3D6 M.D.', 1, '400 feet (122 m) thrown', NULL, NULL, NULL, NULL, NULL, 'Bone or shell trident that can be thrown 400 feet (122 m) and comes back by magic. As a long weapon it may be of the collapsible kind, folding to one-third length (about 2 ft/0.6 m) for carrying. Grown from a vertebrate or a crustacean, with a jagged edge like a crab claw or clamshell; enchanted to return to the thrower. 500-650 P.P.E. to create. As a Lemurian melee Bio-Weapon it can hurt beings harmed only by special attacks (vampires, werebeasts and the like), has 1D6x10+20 M.D.C. of its own if targeted, regrowing 1D6 M.D.C. per minute, and needs no host.', 'Rifts World Book 32: Lemuria p.131-132', NULL),
  ('lemurian-coral-bio-weapon-dagger-knife', 'Coral Bio-Weapon: Dagger or Knife', 'rifts', 'weapon', NULL, NULL, 'Never sold by Lemurians; all Bio-Weapons are valued as magic weapons at 50,000-200,000 credits depending on the weapon, its damage and special abilities (general figure, printed 131).', '1D4 M.D. melee; Bio-Energy blast 1D6 M.D.', 1, 'Blast 200 feet (61 m) above water, 240 feet (73 m) underwater', '5 Bio-Energy blasts; recharges after two hours, or on a ley line or nexus, or when a mage puts in 21 P.P.E.', NULL, NULL, NULL, NULL, 'Coral dagger or knife that strikes for 1D4 M.D. and shoots Bio-Energy for 1D6 M.D., five blasts per charge. Anyone can use it while charged; W.P. Energy Pistol gives its strike bonuses to the blasts. On a ley line the blasts, their number and damage are doubled, tripled at a nexus. 550-700 P.P.E. to create. As a Lemurian melee Bio-Weapon it can hurt beings harmed only by special attacks (vampires, werebeasts and the like), has 1D6x10+20 M.D.C. of its own if targeted, regrowing 1D6 M.D.C. per minute, and needs no host. Its powers are triggered mentally through Telepathy, Empathic Connection with Animals or a Biomancer''s Communicate with Plants and Animals; P.P.E. held in it cannot be drawn on for spells.', 'Rifts World Book 32: Lemuria p.132', NULL),
  ('lemurian-coral-bio-weapon-spear', 'Coral Bio-Weapon: Spear', 'rifts', 'weapon', NULL, NULL, 'Never sold by Lemurians; all Bio-Weapons are valued as magic weapons at 50,000-200,000 credits depending on the weapon, its damage and special abilities (general figure, printed 131).', '1D6+2 M.D. melee; Bio-Energy blast 2D6 M.D.', 1, 'Blast 2,000 feet (610 m) above water, 2,400 feet (731.5 m) underwater', '5 Bio-Energy blasts; recharges after two hours, or on a ley line or nexus, or when a mage puts in 21 P.P.E.', NULL, NULL, NULL, NULL, 'Coral spear that strikes for 1D6+2 M.D. and shoots Bio-Energy for 2D6 M.D., five blasts per charge. Anyone can use it while charged; W.P. Energy Rifle gives its strike bonuses to the blasts. On a ley line the blasts, their number and damage are doubled, tripled at a nexus. 550-700 P.P.E. to create. As a long weapon it may be of the collapsible kind, folding to one-third length (about 2 ft/0.6 m) for carrying. As a Lemurian melee Bio-Weapon it can hurt beings harmed only by special attacks (vampires, werebeasts and the like), has 1D6x10+20 M.D.C. of its own if targeted, regrowing 1D6 M.D.C. per minute, and needs no host. Its powers are triggered mentally through Telepathy, Empathic Connection with Animals or a Biomancer''s Communicate with Plants and Animals; P.P.E. held in it cannot be drawn on for spells.', 'Rifts World Book 32: Lemuria p.132', NULL),
  ('lemurian-coral-bio-weapon-short-sword', 'Coral Bio-Weapon: Short Sword', 'rifts', 'weapon', NULL, NULL, 'Never sold by Lemurians; all Bio-Weapons are valued as magic weapons at 50,000-200,000 credits depending on the weapon, its damage and special abilities (general figure, printed 131).', '2D4 M.D. melee; Bio-Energy blast 3D4 M.D.', 1, 'Blast 1,000 feet (305 m) above water, 1,200 feet (366 m) underwater', '5 Bio-Energy blasts; recharges after two hours, or on a ley line or nexus, or when a mage puts in 21 P.P.E.', NULL, NULL, NULL, NULL, 'Coral short sword that strikes for 2D4 M.D. and shoots Bio-Energy for 3D4 M.D., five blasts per charge. Anyone can use it while charged; W.P. Energy Pistol gives its strike bonuses to the blasts. On a ley line the blasts, their number and damage are doubled, tripled at a nexus. 550-700 P.P.E. to create. As a Lemurian melee Bio-Weapon it can hurt beings harmed only by special attacks (vampires, werebeasts and the like), has 1D6x10+20 M.D.C. of its own if targeted, regrowing 1D6 M.D.C. per minute, and needs no host. Its powers are triggered mentally through Telepathy, Empathic Connection with Animals or a Biomancer''s Communicate with Plants and Animals; P.P.E. held in it cannot be drawn on for spells.', 'Rifts World Book 32: Lemuria p.132', NULL),
